import java.util.*;

class Solution {
    public ListNode swapPairs(ListNode head) {
        if (head == null || head.next == null) return head;  // 0 or 1 node left
        ListNode second = head.next;
        head.next = swapPairs(second.next);  // rest of the list, already swapped
        second.next = head;                  // second node now comes first
        return second;
    }
}

