class Solution:
    def swapPairs(self, head: Optional[ListNode]) -> Optional[ListNode]:
        d = ListNode(0, head); p = d
        while p.next and p.next.next:
            a, b = p.next, p.next.next
            a.next = b.next; b.next = a; p.next = b; p = a
        return d.next
